/**
 * The vendored text Arya Qwen ships, read from disk once.
 *
 * Three files live next to this module:
 *
 *   - `prompt.md` — Qwen Code's system prompt (Core Mandates, Primary Workflows,
 *     Operational Guidelines), tool names mapped onto this harness;
 *   - `checkpoint-prompt.md` — Qwen Code's compression prompt, which asks for an
 *     `<analysis>` scratchpad and a 9-section `<state_snapshot>` envelope;
 *   - `summary-suffix.md` — Qwen Code's resume trailer, appended after a summary
 *     rather than regenerated by the summarizer on every fold.
 *
 * The plan-mode section is shared with Arya Standard: it describes the harness's
 * plan mode, which is the same in both presets.
 *
 * @module dsh-aryacode-polish-arya-qwen-files
 */

import { readFileSync } from 'node:fs'

const FILES = new Map([
  ['prompt', 'prompt.md'],
  ['checkpoint', 'checkpoint-prompt.md'],
  ['suffix', 'summary-suffix.md'],
])

/** @type {Map<string, string>} */
const cache = new Map()

/**
 * Read one vendored file.
 * @param {string} key one of `prompt`, `checkpoint`, `suffix`.
 * @returns {string} the file's text.
 */
function read(key) {
  const name = FILES.get(key)
  if (name === undefined) throw new Error(`arya-qwen: unknown vendored file ${key}`)
  const cached = cache.get(key)
  if (cached !== undefined) return cached
  const text = readFileSync(new URL(`./${name}`, import.meta.url), 'utf8')
  cache.set(key, text)
  return text
}

/** Qwen Code's system prompt, already mapped onto this harness's tools. */
export function qwenBasePrompt() {
  return read('prompt')
}

/** Qwen Code's history-compression prompt. */
export function qwenCheckpointPrompt() {
  return read('checkpoint')
}

/** Qwen Code's resume trailer, appended after the summary body. */
export function qwenSummarySuffix() {
  return read('suffix')
}
